DO $p3c_do$
DECLARE
  v_data jsonb := $p3c_json${"standard":{"code":"DWA-M-179-1","title_de":"Dezentrale Anlagen zur Niederschlagswasserbehandlung - Teil 1: Allgemeines sowie Einleitung ins Oberflaechengewaesser","title_en":"Decentralized Stormwater Treatment Systems - Part 1: General Aspects and Discharge to Surface Waters","version":"September 2024 (Entwurf)"},"worksheets":[{"code":"M179-01","title_de":"Projektregistrierung","title_en":"Project Registration","phase":1,"archetype":"registration","order_index":1,"description":"Captures project identification: number, name, responsible engineer, client, location, regulatory authority, permit reference. Documents applicable regulation (DWA-M 179-1) and target compartment (Oberflaechengewaesser) per §4 and Tabelle 3."},{"code":"M179-02","title_de":"Einzugsgebiet und Flaechenermittlung","title_en":"Catchment Area and Surface Definition","phase":1,"archetype":"data_collection","order_index":2,"description":"Defines the connected impervious catchment area A_b,a per §8.1. Documents surface types (Dachflaechen, Verkehrsflaechen per Bild 1). Records Ψ_s = 1 per this Merkblatt. Verifies A_b,a typically ≤ 5,000 m² applicability per §1."},{"code":"M179-03","title_de":"Flaechenklassifizierung und stoffliche Belastung","title_en":"Surface Classification and Pollution Loading","phase":2,"archetype":"data_collection","order_index":3,"description":"Classifies each surface per DWA-A 102-2 Belastungskategorien (I, II, III). Documents pollution loading from Tabelle 4. Records applicable technical rule from Tabelle 3. Notes prohibition on mixing Kategorie I with II/III (§8.2)."},{"code":"M179-04","title_de":"Behandlungsziel-Bestimmung","title_en":"Treatment Target Determination","phase":2,"archetype":"data_collection","order_index":4,"description":"Derives required overall treatment efficiency η_ges from surface category per DWA-A 102-2: Kat. II ≥ 47%, Kat. III ≥ 63%. Emission target AFS63 ≤ 280 kg/(ha·a) per §8.2. For mixed categories the stricter requirement governs."},{"code":"M179-05","title_de":"Behandlungsverfahren-Auswahl","title_en":"Treatment Method Selection","phase":2,"archetype":"data_collection","order_index":5,"description":"Documents selected treatment approach (Sedimentation §6.2.2, Filtration §6.2.3, or combination). Records flow-split configuration (Fall 1-4 from Bild 3). Documents full-stream or partial treatment."},{"code":"M179-06","title_de":"Verfahrensspezifische Wirkungsgrad-Daten","title_en":"Treatment Performance Data","phase":2,"archetype":"data_collection","order_index":6,"description":"Records specific treatment efficiency η_BV. For sedimentation: Bild 4 regression η_BV = a·exp(-b·q_A,max) with a(AFS63)=0.6670, b(AFS63)=0.1279. For filtration: η_BV = 95% per §7.3.2. Design limits: sedimentation q_A,max ≤ 4 m/h; filter v_F = 0.05-2.5 m/h; filter thickness ≥ 0.2 m."},{"code":"M179-07","title_de":"Eingangsdaten-Zusammenfassung","title_en":"Input Data Summary","phase":2,"archetype":"summary","order_index":7,"description":"Phase 2 boundary summary: A_b,a, surface categories, η_ges, treatment method, η_BV, q_A,max, Ψ_s. Provides consolidated inputs for Phase 3 calculations."},{"code":"M179-08","title_de":"Hydraulischer Wirkungsgrad","title_en":"Hydraulic Efficiency Calculation","phase":3,"archetype":"calculation","order_index":8,"description":"Implements Gleichung (2): η_hyd = η_ges / η_BV. First calculation step. Validity: η_hyd ≥ 50% (below 50% not meaningful per §6.1). If η_hyd > 100%, a higher η_BV is needed."},{"code":"M179-09","title_de":"Kritische Regenspende","title_en":"Critical Rain Intensity","phase":3,"archetype":"calculation","order_index":9,"description":"Implements Gleichung (1): r_krit = 0,1201·exp(0,0655·η_hyd). Alternatively uses Tabelle 5 lookup. Based on Leutnant et al. (2020). Validity range: η_hyd = 50–100%."},{"code":"M179-10","title_de":"Abflussaufteilung und kritischer Abfluss","title_en":"Flow Split and Critical Flow","phase":3,"archetype":"calculation","order_index":10,"description":"Implements Gleichung (3): Q_krit = A_b,a · Ψ_s · r_krit / 10.000. Evaluates flow-split configuration (Fall 1-4 from Bild 3). For Fall 4 (pre-treatment throttle): min Q_krit ≥ 5 l/s per DWA-A 166. Ψ_s = 1 per §8.2."},{"code":"M179-11","title_de":"Sedimentationsflaechen-Bemessung","title_en":"Sedimentation Area Sizing","phase":3,"archetype":"calculation","order_index":11,"description":"Implements Gleichung (4): A_sed = 3,6 · Q_krit / q_A,max. Sludge storage ≥ 15 kg/(m²·a) AFS, density 2,0 g/cm³. Design constraints: max throughput deviation 20%, turbulence-free flow. Anhang A examples A.2.2, A.2.3."},{"code":"M179-12","title_de":"Filterflaechen-Bemessung","title_en":"Filter Area Sizing","phase":3,"archetype":"calculation","order_index":12,"description":"Implements Gleichung (5): A_F = A_b,a · 0,01 (1% filter area ratio). AFS63 ≤ 7 kg/(m²·a) for ≥ 12 months. With effective pre-treatment, ratio may be reduced (Anh. A.3.3). Anhang A examples A.3.2, A.4."},{"code":"M179-13","title_de":"Berechnungs-Zusammenfassung","title_en":"Calculation Summary","phase":3,"archetype":"summary","order_index":13,"description":"Phase 3 boundary summary: η_hyd, r_krit, Q_krit, and applicable sizing (A_sed and/or A_F). Documents the complete parameter chain from target η_ges to design area."},{"code":"M179-14","title_de":"Standortspezifische Einflussfaktor-Bewertung","title_en":"Site-Specific Factor Assessment","phase":5,"archetype":"calculation","order_index":14,"description":"Implements site-specific scoring from Tabelle 6 (§8.3): 8 factors (+1/-1 each). Sum ≤ 1: standard conditions (1-year standtime). Sum = 1: increased sludge → more frequent cleaning. Sum ≥ 3: operational safety at risk."},{"code":"M179-15","title_de":"Bemessungs-Zusammenfassung","title_en":"Design Summary","phase":5,"archetype":"summary","order_index":15,"description":"Compiles final design package: all calculation chain parameters, site-factor assessment, selected treatment method and configuration, required treatment areas, flow-split arrangement. Bridge between calculation and verification."},{"code":"M179-16","title_de":"Betriebliche Anforderungen","title_en":"Operational Requirements","phase":6,"archetype":"verification","order_index":16,"description":"Documents operational requirements from §9 and §8.4: control 1-2/yr, cleaning 1/yr, maintenance ~0.33/yr per Bild 5. Includes Inbetriebnahme requirements (§8.4.6), service instructions per DWA-A 199-1/2, monitoring (≥ 1 year if effectiveness investigation desired)."},{"code":"M179-17","title_de":"Konformitaets-Zusammenfassung","title_en":"Compliance Summary","phase":6,"archetype":"verification","order_index":17,"description":"Final compliance determination: verifies η_ges target met, areas adequate, site factor sum within acceptable range (Σ < 3), operational plan feasible. Documents PASS/FAIL per criterion. Records cost considerations per §8.4.2 (dynamic cost comparison)."}],"sections":[{"ws_code":"M179-01","code":"A","title_de":"Purpose and Regulatory Context","order_index":1,"parent_code":null},{"ws_code":"M179-01","code":"B","title_de":"Input Parameters","order_index":2,"parent_code":null},{"ws_code":"M179-01","code":"C","title_de":"Worksheet-Specific Content","order_index":3,"parent_code":null},{"ws_code":"M179-01","code":"D","title_de":"Results / Derived Values","order_index":4,"parent_code":null},{"ws_code":"M179-01","code":"F","title_de":"Results Summary","order_index":5,"parent_code":null},{"ws_code":"M179-01","code":"J","title_de":"Output Transfer Table","order_index":6,"parent_code":null},{"ws_code":"M179-01","code":"K","title_de":"Notes and Assumptions","order_index":7,"parent_code":null},{"ws_code":"M179-01","code":"L","title_de":"Approval","order_index":8,"parent_code":null},{"ws_code":"M179-01","code":"M","title_de":"Workflow Connection","order_index":9,"parent_code":null},{"ws_code":"M179-02","code":"A","title_de":"Purpose and Regulatory Context","order_index":1,"parent_code":null},{"ws_code":"M17