9-05","section_code":"C","symbol":"treatment_method","label_de":"Gewaehltes Behandlungsverfahren","label_en":"Selected treatment method","data_type":"enum","unit":null,"is_required":true,"enum_values":[{"value":"sedimentation","label_de":"Sedimentation (Dichtetrennung)","label_en":"Sedimentation (density separation)","order_index":1,"regulation_reference":"§6.2.2"},{"value":"filtration_oberflaeche","label_de":"Oberflaechenfiltration","label_en":"Surface filtration","order_index":2,"regulation_reference":"§6.2.3, §7.3.2"},{"value":"filtration_raum","label_de":"Raumfiltration","label_en":"Volume filtration","order_index":3,"regulation_reference":"§6.2.3"},{"value":"kombination_sed_filt","label_de":"Kombination Sedimentation + Filtration","label_en":"Combination sed. + filtration","order_index":4,"regulation_reference":"Anh. A.3.3, A.4"},{"value":"adsorption_ionentausch","label_de":"Adsorption / Ionentausch","label_en":"Adsorption / ion exchange","order_index":5,"regulation_reference":"§6.2.4"},{"value":"faellung","label_de":"Faellung","label_en":"Precipitation","order_index":6,"regulation_reference":"§6.2.5"}],"validation_rules":{"raw":"enum:treatment_method"},"clause_reference":"§6.2.2, §6.2.3, Anh. A","description":"Selected treatment principle: sedimentation, filtration, combination, or other (z.B. Adsorption per §6.2.4, Faellung per §6.2.5).","consumer_worksheets":["M179-06","M179-11","M179-12","M179-13"]},{"ws_code":"M179-05","section_code":"C","symbol":"flow_split_case","label_de":"Abflussaufteilung (Fall 1-4)","label_en":"Flow split case (Fall 1-4)","data_type":"enum","unit":null,"is_required":true,"enum_values":[{"value":"fall_1","label_de":"Fall 1 (Drosselung nach Behandlung)","label_en":"Case 1 (throttle downstream of treatment)","order_index":1,"regulation_reference":"§7.2, Bild 3"},{"value":"fall_2","label_de":"Fall 2 (Drosselung nach Behandlung)","label_en":"Case 2 (throttle downstream of treatment)","order_index":2,"regulation_reference":"§7.2, Bild 3"},