"},"clause_reference":"§7.3.2, Tab.2","description":"Filter velocity v_F. Recommended Oberflaechenfiltration: 0,05–2,5 m/h. Raumfiltration: 2,5–15 m/h.","consumer_worksheets":["M179-12"]},{"ws_code":"M179-06","section_code":"C","symbol":"filter_thickness","label_de":"Filtermaechtigkeit","label_en":"Filter thickness","data_type":"number","unit":"m","is_required":false,"enum_values":null,"validation_rules":{"raw":"RULE-021"},"clause_reference":"§7.3.2","description":"Filter bed thickness. Minimum 0,2 m; values < 0,2 m not recommended.","consumer_worksheets":["M179-12"]},{"ws_code":"M179-06","section_code":"C","symbol":"regression_a_AFS63","label_de":"Bild 4: Regressionsparameter a (AFS63)","label_en":"Bild 4 regression a (AFS63)","data_type":"number","unit":"-","is_required":false,"enum_values":null,"validation_rules":{"raw":"fixed at 0.6670"},"clause_reference":"§7.3.1, Bild 4","description":"Regression coefficient a for AFS63 in η_BV = a · exp(-b·q_A,max). Per Fuchs & Kemper 2018.","consumer_worksheets":["M179-06"]},{"ws_code":"M179-06","section_code":"C","symbol":"regression_b_AFS63","label_de":"Bild 4: Regressionsparameter b (AFS63)","label_en":"Bild 4 regression b (AFS63)","data_type":"number","unit":"-","is_required":false,"enum_values":null,"validation_rules":{"raw":"fixed at 0.1279"},"clause_reference":"§7.3.1, Bild 4","description":"Regression coefficient b for AFS63 in η_BV = a · exp(-b·q_A,max). Per Fuchs & Kemper 2018.","consumer_worksheets":["M179-06"]},{"ws_code":"M179-06","section_code":"C","symbol":"sludge_storage_min","label_de":"Mind. Schlammspeicher","label_en":"Min sludge storage","data_type":"number","unit":"kg/(m²*a)","is_required":false,"enum_values":null,"validation_rules":{"raw":"RULE-016"},"clause_reference":"§7.3.1, §8.2","description":"Minimum sludge storage of 15 kg/(m²·a) AFS for sedimentation facilities.","consumer_worksheets":["M179-11"]},{"ws_code":"M179-06","section_code":"C","symbol":"sludge_density","label_de":"Schlammdichte","label_en":"Sludge density","data_type":"number","unit":"g/cm³","is_required":false,"enum_values":null,"validation_rules":{"raw":"RULE-017"},"clause_reference":"§8.2","description":"Sludge density assumption for volume calculation: 2,0 g/cm³.","consumer_worksheets":["M179-11"]},{"ws_code":"M179-06","section_code":"C","symbol":"filter_AFS63_max_load","label_de":"Max. AFS63-Filterflaechenbelastung","label_en":"Max AFS63 filter loading","data_type":"number","unit":"kg/(m²*a)","is_required":false,"enum_values":null,"validation_rules":{"raw":"RULE-022"},"clause_reference":"§7.3.2, §8.2","description":"Maximum filter area AFS63 loading 7 kg/(m²·a) for minimum 12 months Standzeit.","consumer_worksheets":["M179-12"]},{"ws_code":"M179-08","section_code":"D","symbol":"eta_hyd","label_de":"Hydraulischer Wirkungsgrad","label_en":"Hydraulic efficiency","data_type":"number","unit":"%","is_required":true,"enum_values":null,"validation_rules":{"raw":"RULE-008, RULE-009"},"clause_reference":"§6.1, §8.2, Tab.2","description":"Hydraulic efficiency = treated proportion of annual rain runoff V_R,aM. Computed from Gl. (2). Validity: ≥ 50% (below not meaningful per §6.1).","consumer_worksheets":["M179-09","M179-13","M179-17"]},{"ws_code":"M179-09","section_code":"D","symbol":"r_krit","label_de":"Kritische Regenspende","label_en":"Critical rain intensity","data_type":"number","unit":"l/(s*ha)","is_required":true,"enum_values":null,"validation_rules":{"raw":"use Tab.5 or Gl. (1)"},"clause_reference":"§7.2, Tab.2","description":"Critical rain intensity from η_hyd via Gleichung (1) or Tabelle 5 lookup.","consumer_worksheets":["M179-10","M179-13"]},{"ws_code":"M179-10","section_code":"D","symbol":"Q_krit","label_de":"Zu behandelnder kritischer Abfluss","label_en":"Critical flow to treat","data_type":"number","unit":"l/s","is_required":true,"enum_values":null,"validation_rules":{"raw":"RULE-011, RULE-012"},"clause_reference":"§8.2, Tab.2","description":"Critical flow to be treated, computed from Gl. (3). For Abflussaufteilung Fall 4 (technical pre-throttle): minimum 5 l/s per Arbeitsblatt DWA-A 166.","consumer_worksheets":["M179-11","M179-13"]},{"ws_code":"M179-11","section_code":"D","symbol":"A_sed","label_de":"Sedimentationswirksame Flaeche","label_en":"Sedimentation effective area","data_type":"number","unit":"m²","is_required":false,"enum_values":null,"validation_rules":{"raw":"applicable if treatment_method includes sedimentation"},"clause_reference":"§8.2, Tab.2","description":"Sedimentation effective area as base or projected area beneath Schraegklaerer (lamellar settlers).","consumer_worksheets":["M179-13","M179-15"]},{"ws_code":"M179-12","section_code":"D","symbol":"A_F","label_de":"Filterflaeche","label_en":"Filter area","data_type":"number","unit":"m²","is_required":false,"enum_values":null,"validation_rules":{"raw":"RULE-023, RULE-024"},"clause_reference":"§8.2, Tab.2","description":"Filter area = 1% of A_b,a (Gl. 5). With effective pre-treatment, ratio may be reduced (§8.2, Anh. A.3.3).","consumer_worksheets":["M179-13","M179-15"]},{"ws_code":"M179-11","section_code":"C","symbol":"A_eff","label_de":"Rechn. sedim.-wirksame Flaeche (Schraegklaerer)","label_en":"Computed effective sedimentation area (lamellar settlers)","data_type":"number","unit":"m²","is_required":false,"enum_values":null,"validation_rules":null,"clause_reference":"Tab.2","description":"Computed effective sedimentation area for lamellar settlers (Schraegklaerer).","consumer_worksheets":["M179-13"]},{"ws_code":"M179-11","section_code":"C","symbol":"A_OB","label_de":"Oberflaeche/Grundflaeche Sedimentationsanlage","label_en":"Surface/base area of sedimentation facility","data_type":"number","unit":"m²","is_required":false,"enum_values":null,"validation_rules":null,"clause_reference":"Tab.2","description":"Surface or base area of sedimentation facility.","consumer_worksheets":["M179-15"]},{"ws_code":"M179-14","section_code":"C","symbol":"factor_verkehrsverhaeltnisse","label_de":"Verkehrsverhaeltnisse (Kreisverkehr, LSA, Steigungen)","label_en":"Traffic conditions (roundabouts, signals, slopes)","data_type":"boolean","unit":"(+1)","is_required":true,"enum_values":null,"validation_rules":null,"clause_reference":"§8.3, Tab.6","description":"+1 if applicable: Kreisverkehr, Lichtsignalanlagen, vermehrte Bremsvorgaenge durch Steigungen/Gefaelle.","consumer_worksheets":["M179-14"]},{"ws_code":"M179-14","section_code":"C","symbol":"factor_schwerlast_hoch","label_de":"Hoher Schwerlastverkehr (>8% DTV)","label_en":"Heavy traffic > 8% DTV","data_type":"boolean","unit":"(+1)","is_required":true,"enum_values":null,"validation_rules":null,"clause_reference":"§8.3, Tab.6","description":"+1 if heavy traffic exceeds 8% of DTV.","consumer_worksheets":["M179-14"]},{"ws_code":"M179-14","section_code":"C","symbol":"factor_stoffeintraege","label_de":"Regelm. besondere Stoffeintraege (Vegetation, Landwirtschaft, Bau)","label_en":"Regular special inputs (vegetation, agriculture, construction)","data_type":"boolean","unit":"(+1)","is_required":true,"enum_values":null,"validation_rules":null,"clause_reference":"§8.3, Tab.6","description":"+1 if regular special pollutant inputs: tree canopy, transport firms, agriculture, construction.","consumer_worksheets":["M179-14"]},{"ws_code":"M179-14","section_code":"C","symbol":"factor_sonstige_erhoehend","label_de":"Sonstige erhoehende Faktoren (Winterdienst, Randbebauung)","label_en":"Other increasing factors (winter service, surrounding buildings)","data_type":"boolean","unit":"(+1)","is_required":true,"enum_values":null,"validation_rules":null,"clause_reference":"§8.3, Tab.6","description":"+1 if other increasing factors apply.","consumer_worksheets":["M179-14"]},{"ws_code":"M179-14","section_code":"C","symbol":"factor_strassenreinigung","label_de":"Haeufige Strassenreinigung","label_en":"Frequent street cleaning","data_type":"boolean","unit":"(-1)","is_required":true,"enum_values":null,"validation_rules":null,"clause_reference":"§8.3, Tab.6","description":"-1 if frequent street cleaning is in place.","consumer_worksheets":["M179-14"]},{"ws_code":"M179-14","section_code":"C","symbol":"factor_schwerlast_ausgeschlossen","label_de":"Schwerlastverkehr nahezu ausgeschlossen","label_en":"Heavy traffic essentially excluded","data_type":"boolean","unit":"(-1)","is_required":true,"enum_values":null,"validation_rules":null,"clause_reference":"§8.3, Tab.6","description":"-1 if heavy traffic is essentially excluded.","consumer_worksheets":["M179-14"]},{"ws_code":"M179-14","section_code":"C","symbol":"factor_oberird_ableitung","label_de":"Oberirdische Ableitung (Gerinne, Transportmulden)","label_en":"Open-channel surface conveyance","data_type":"boolean","unit":"(-1)","is_required":true,"enum_values":null,"validation_rules":null,"clause_reference":"§8.3, Tab.6","description":"-1 if conveyance is via open channels or transport swales with significant solids retention via rough surfaces or barriers.","consumer_worksheets":["M179-14"]},{"ws_code":"M179-14","section_code":"C","symbol":"factor_sonstige_mindernd","label_de":"Sonstige mindernde Faktoren (fehlende Randbebauung)","label_en":"Other decreasing factors (no surrounding buildings)","data_type":"boolean","unit":"(-1)","is_required":true,"enum_values":null,"validation_rules":null,"clause_reference":"§8.3, Tab.6","description":"-1 if other decreasing factors apply (e.g. absence of surrounding buildings → air-driven solids transport out of A_b,a).","consumer_worksheets":["M179-14"]},{"ws_code":"M179-14","section_code":"D","symbol":"site_factor_sum","label_de":"Summe standortspez. Faktoren","label_en":"Sum of site-specific factors","data_type":"number","unit":"(integer)","is_required":true,"enum_values":null,"validation_rules":{"raw":"RULE-025, RULE-026, RULE-027"},"clause_reference":"§8.3, Tab.6","description":"Sum of all +1 / -1 site factors. ≤ 1 = standard; = 1 = increased sludge → more cleaning; ≥ 3 = operational risk.","consumer_worksheets":["M179-15","M179-17"]},{"ws_code":"M179-16","section_code":"C","symbol":"kontrolle_frequency","label_de":"Haeufigkeit Kontrolle","label_en":"Control frequency","data_type":"number","unit":"1/a","is_required":true,"enum_values":null,"validation_rules":{"raw":"Bild 5: 1-2/a typical"},"clause_reference":"§9, Bild 5","description":"Inspection / control frequency. Bild 5 example: 1-2× per year.","consumer_worksheets":["M179-17"]},{"ws_code":"M179-16","section_code":"C","symbol":"reinigung_frequency","label_de":"Haeufigkeit Reinigung","label_en":"Cleaning frequency","data_type":"number","unit":"1/a","is_required":true,"enum_values":null,"validation_rules":{"raw":"Bild 5: ~1/a typical"},"clause_reference":"§9, Bild 5","description":"Cleaning frequency. Bild 5 example: 1× per year.","consumer_worksheets":["M179-17"]},{"ws_code":"M179-16","section_code":"C","symbol":"wartung_frequency","label_de":"Haeufigkeit Wartung","label_en":"Maintenance frequency","data_type":"number","unit":"1/a","is_required":true,"enum_values":null,"validation_rules":{"raw":"Bild 5: ~0.33/a typical"},"clause_reference":"§9, Bild 5","description":"Maintenance (Wartung) frequency. Bild 5 example: ~every 3 years (~0.33/a).","consumer_worksheets":["M179-17"]},{"ws_code":"M179-16","section_code":"C","symbol":"monitoring_planned","label_de":"Monitoring >=1 Jahr geplant?","label_en":"Monitoring >=1 yr planned?","data_type":"boolean","unit":null,"is_required":false,"enum_values":null,"validation_rules":null,"clause_reference":"§9","description":"Flag: monitoring of ≥ 1 year planned (Wasserstand/Durchfluss, saisonale Bewertung, AFS63-Depot nach 1 Jahr).","consumer_worksheets":["M179-17"]},{"ws_code":"M179-16","section_code":"C","symbol":"betriebsanweisung_status","label_de":"Status Betriebsanweisung (DWA-A 199)","label_en":"Operating instructions status","data_type":"enum","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"enum:doc_status"},"clause_reference":"§8.4.4, DWA-A 199","description":"Status of Betriebsanweisung (and Dienstanweisung if applicable) per DWA-A 199 Teil 1/2.","consumer_worksheets":["M179-17"]},{"ws_code":"M179-16","section_code":"C","symbol":"inbetriebnahme_date","label_de":"Inbetriebnahme-Datum","label_en":"Commissioning date","data_type":"date","unit":null,"is_required":false,"enum_values":null,"validation_rules":null,"clause_reference":"§8.4.6","description":"Planned or actual commissioning date. Funktionspruefung must be performed beforehand.","consumer_worksheets":["M179-17"]},{"ws_code":"M179-17","section_code":"D","symbol":"compliance_verdict","label_de":"Konformitaetsurteil","label_en":"Compliance verdict","data_type":"enum","unit":null,"is_required":true,"enum_values":[{"value":"compliant","label_de":"konform","label_en":"compliant","order_index":1,"regulation_reference":"methodology"},{"value":"compliant_with_conditions","label_de":"konform mit Auflagen","label_en":"compliant with conditions","order_index":2,"regulation_reference":"methodology"},{"value":"not_compliant","label_de":"nicht konform","label_en":"not compliant","order_index":3,"regulation_reference":"methodology"},{"value":"insufficient_data","label_de":"unzureichende Daten","label_en":"insufficient data","order_index":4,"regulation_reference":"methodology"}],"validation_rules":{"raw":"enum:compliance_verdict"},"clause_reference":"§8.2, §10","description":"Overall compliance verdict (compliant / compliant_with_conditions / not_compliant / insufficient_data).","consumer_worksheets":null},{"ws_code":"M179-03","section_code":"C","symbol":"cat_I_mixing_violation","label_de":"Vermischung Kat. I mit II/III","label_en":"Cat. I mixed with II/III","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"RULE-003"},"clause_reference":"§8.2","description":"Derived flag: TRUE if Kat. I runoff is combined with Kat. II or III. Forbidden per §8.2.","consumer_worksheets":["M179-17"]},{"ws_code":"M179-03","section_code":"C","symbol":"cat_II_III_mixing","label_de":"Vermischung Kat. II mit III","label_en":"Cat. II mixed with III","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"RULE-004"},"clause_reference":"§8.2","description":"Derived flag: TRUE if Kat. II and Kat. III runoff are combined. Allowed but strictest (Kat. III) requirement applies to the combined area.","consumer_worksheets":["M179-04","M179-17"]},{"ws_code":"M179-12","section_code":"C","symbol":"vorbehandlung_present","label_de":"Wirksame Vorbehandlung vorhanden","label_en":"Effective pre-treatment present","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"RULE-023"},"clause_reference":"§8.2 (line 665), Anh. A.3.3","description":"Flag: is effective pre-treatment (e.g. sedimentation) present? If TRUE, the 1% Filterflaechenverhaeltnis may be reduced per §8.2.","consumer_worksheets":["M179-12"]},{"ws_code":"M179-06","section_code":"C","symbol":"filter_type","label_de":"Filtertyp","label_en":"Filter type","data_type":"enum","unit":null,"is_required":false,"enum_values":[{"value":"oberflaechenfiltration","label_de":"Oberflaechenfiltration (empfohlen)","label_en":"Surface filtration (recommended)","order_index":1,"regulation_reference":"§7.3.2 line 580"},{"value":"raumfiltration","label_de":"Raumfiltration","label_en":"Volume filtration","order_index":2,"regulation_reference":"§7.3.2 line 578"}],"validation_rules":{"raw":"enum:filter_type"},"clause_reference":"§7.3.2","description":"Filter subtype: oberflaechenfiltration (recommended for stormwater) vs raumfiltration (different v_F range applies).","consumer_worksheets":["M179-12"]},{"ws_code":"M179-11","section_code":"C","symbol":"throughput_deviation_pct","label_de":"Durchsatzabweichung Anlage","label_en":"Facility throughput deviation","data_type":"number","unit":"%","is_required":false,"enum_values":null,"validation_rules":{"raw":"RULE-015"},"clause_reference":"§7.3.1","description":"Throughput deviation of the sedimentation facility from design value. Maximum 20% per §7.3.1.","consumer_worksheets":["M179-11"]},{"ws_code":"M179-16","section_code":"C","symbol":"funktionspruefung_done","label_de":"Funktionspruefung vor Inbetriebnahme erfolgt","label_en":"Pre-commissioning function test done","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"RULE-031"},"clause_reference":"§8.4.6","description":"Flag: function test performed before commissioning per §8.4.6.","consumer_worksheets":["M179-17"]},{"ws_code":"M179-16","section_code":"C","symbol":"wartungsvertrag_present","label_de":"Wartungsvertrag vorhanden","label_en":"Maintenance contract in place","data_type":"boolean","unit":null,"is_required":false,"enum_values":null,"validation_rules":{"raw":"RULE-034"},"clause_reference":"§9","description":"Flag: maintenance contract is in place. Recommended for complex / private operations per §9.","consumer_worksheets":["M179-17"]},{"ws_code":"M179-16","section_code":"C","symbol":"fachkundige_person_assigned","label_de":"Fachkundige Person fuer Kontrolle/Reinigung/Wartung","label_en":"Qualified personnel assigned","data_type":"boolean","unit":null,"is_required":true,"enum_values":null,"validation_rules":{"raw":"RULE-034"},"clause_reference":"§9","description":"Flag: qualified personnel assigned for control/cleaning/maintenance per §9.","consumer_worksheets":["M179-17"]}],"equations":[{"ws_code":"M179-09","equation_number":"1","formula":"r_krit = 0.1201 * exp(0.0655 * eta_hyd)","input_symbols":["eta_hyd"],"output_symbol":"r_krit","clause_reference":"§7.2","description":"Kritische Regenspende aus hydraulischem Wirkungsgrad"},{"ws_code":"M179-08","equation_number":"2","formula":"eta_hyd = eta_ges / eta_BV","input_symbols":["eta_ges","eta_BV"],"output_symbol":"eta_hyd","clause_reference":"§8.2","description":"Hydraulischer Wirkungsgrad aus Gesamt- und Verfahrenswirkungsgrad"},{"ws_code":"M179-10","equation_number":"3","formula":"Q_krit = A_b_a * Psi_s * r_krit / 10000","input_symbols":["A_b_a","Psi_s","r_krit"],"output_symbol":"Q_krit","clause_reference":"§8.2","description":"Kritischer Abfluss aus angeschlossener Flaeche und Regenspende"},{"ws_code":"M179-11","equation_number":"4","formula":"A_sed = 3.6 * Q_krit / q_A_max","input_symbols":["Q_krit","q_A_max"],"output_symbol":"A_sed","clause_reference":"§8.2","description":"Sedimentationswirksame Flaeche"},{"ws_code":"M179-12","equation_number":"5","formula":"A_F = A_b_a * 0.01","input_symbols":["A_b_a"],"output_symbol":"A_F","clause_reference":"§8.2","description":"Filterflaeche als 1% der angeschlossenen Flaeche"},{"ws_code":"M179-06","equation_number":"Bild 4 regression","formula":"eta_BV = a_AFS63 * exp(-b_AFS63 * q_A_max)","input_symbols":["q_A_max","regression_a_AFS63","regression_b_AFS63"],"output_symbol":"eta_BV","clause_reference":"§7.3.1, Bild 4","description":"Sedimentationswirkungsgrad AFS63 als Funktion der Oberflaechenbeschickung"}],"compliance":[{"ws_code":"M179-01","code":"REQ-01","title_de":"Anwendungsbereich: A_b,a typisch <= 5.000 m²","condition":"A_b_a <= 5000","description":"DWA-M 179-1 applies to dezentrale Anlagen with connected impervious area typically up to 5,000 m². Larger areas should be checked against DWA-A 166 (zentrale Anlagen).","clause_reference":"§1"},{"ws_code":"M179-01","code":"REQ-02","title_de":"Zielkompartiment = Oberflaechengewaesser","condition":"target_compartment == 'oberflaechengewaesser'","description":"DWA-M 179-1 (Teil 1) covers Einleitung in Oberflaechengewaesser. For Grundwasser use Teil 2 / DWA-A 138-1.","clause_reference":"§1, §4.2, Tab.3"},{"ws_code":"M179-01","code":"REQ-03","title_de":"Anwendung technische Regelwerke (Tab.3)","condition":"lookup(Tab.3, catchment, target_compartment) matches selected rule","description":"Apply correct technical rule per Tabelle 3: DWA-A 102-2 for surface-water discharge inside settlement; DWA-A 138-1 for groundwater; REwS for outside-of-settlement roads.","clause_reference":"§4.2, Tab.3"},{"ws_code":"M179-03","code":"REQ-04","title_de":"Verbot Vermischung Kategorie I mit II/III","condition":"NOT (Kat.I mixed with Kat.II or Kat.III)","description":"Mixing non-treatment-requiring runoff (Kat. I) with treatment-requiring runoff (Kat. II/III) is forbidden.","clause_reference":"§8.2"},{"ws_code":"M179-03","code":"REQ-05","title_de":"Vermischung II+III: strengere Anforderung","condition":"if mixed II+III then eta_ges_required >= 63","description":"If Kat. II and Kat. III runoff are unavoidably mixed, the stricter (Kat. III) requirement applies to the combined area.","clause_reference":"§8.2"},{"ws_code":"M179-03","code":"REQ-06","title_de":"Gesamtwirkungsgrad: Kat. II >= 47%","condition":"if Kat.II then eta_ges_required >= 47","description":"Required overall AFS63 efficiency for Kategorie II surfaces is at least 47% (per DWA-A 102-2).","clause_reference":"§8.2 | §8.2, Tab.5"},{"ws_code":"M179-03","code":"REQ-07","title_de":"Gesamtwirkungsgrad: Kat. III >= 63%","condition":"if Kat.III then eta_ges_required >= 63","description":"Required overall AFS63 efficiency for Kategorie III surfaces is at least 63% (per DWA-A 102-2).","clause_reference":"§8.2 | §8.2, Tab.5"},{"ws_code":"M179-08","code":"REQ-08","title_de":"Hydraulischer Wirkungsgrad >= 50%","condition":"eta_hyd >= 50","description":"A hydraulic efficiency η_hyd < 50% is not considered meaningful per §6.1.","clause_reference":"§6.1"},{"ws_code":"M179-08","code":"REQ-09","title_de":"Hydraulischer Wirkungsgrad <= 100%","condition":"eta_hyd <= 100","description":"If η_hyd > 100% is required, a more effective treatment method (higher η_BV) must be chosen.","clause_reference":"§8.2"},{"ws_code":"M179-08","code":"REQ-10","title_de":"Hydraulischer Wirkungsgrad nach Gl. (2)","condition":"abs(eta_hyd - eta_ges_required/eta_BV) < tol","description":"η_hyd is computed via Gleichung (2): η_hyd = η_ges / η_BV.","clause_reference":"§8.2, Gl. (2)"},{"ws_code":"M179-08","code":"REQ-11","title_de":"Kritische Regenspende r_krit","condition":"abs(r_krit - 0.1201*exp(0.0655*eta_hyd)) < tol  OR  r_krit matches Tab.5 lookup","description":"r_krit determined from η_hyd via Gleichung (1) OR Tabelle 5 lookup.","clause_reference":"§7.2, Gl. (1), Tab.5 | §7.2, Tab.5"},{"ws_code":"M179-08","code":"REQ-12","title_de":"Kritischer Abfluss nach Gl. (3)","condition":"abs(Q_krit - A_b_a*Psi_s*r_krit/10000) < tol","description":"Q_krit computed via Gleichung (3): Q_krit = A_b,a · Ψ_s · r_krit / 10.000.","clause_reference":"§8.2, Gl. (3)"},{"ws_code":"M179-08","code":"REQ-13","title_de":"Sedimentation: q_A,max <= 4 m/h fuer eta_BV >= 40% AFS63","condition":"if sedimentation then q_A_max <= 4","description":"To achieve η_BV ≥ 40% for AFS63, sedimentation surface loading must be limited to q_A,max ≤ 4 m/h.","clause_reference":"§7.3.1"},{"ws_code":"M179-08","code":"REQ-14","title_de":"Sedimentation: q_A,max in Bild-4-Anwendungsbereich","condition":"if sedimentation then 1 <= q_A_max <= 10","description":"Bild 4 applicability range: q_A,max = 1 m/h to 10 m/h.","clause_reference":"§7.3.1, Bild 4"},{"ws_code":"M179-08","code":"REQ-15","title_de":"Sedimentation: Durchsatzbegrenzung max. 20%-Abweichung","condition":"throughput deviation <= 20%","description":"Sedimentation facility throughput shall be limited before the facility (deviation max. 20%).","clause_reference":"§7.3.1"},{"ws_code":"M179-08","code":"REQ-16","title_de":"Sedimentation: Schlammspeicher >= 15 kg/(m²·a) AFS","condition":"if sedimentation then sludge_storage capacity covers >= 15 kg/(m²·a)","description":"Sedimentation facilities require sludge storage of >= 15 kg/(m²·a) AFS.","clause_reference":"§7.3.1, §8.2"},{"ws_code":"M179-08","code":"REQ-17","title_de":"Sedimentation: A_sed nach Gl. (4)","condition":"abs(A_sed - 3.6*Q_krit/q_A_max) < tol","description":"A_sed computed via Gleichung (4): A_sed = 3,6 · Q_krit / q_A,max.","clause_reference":"§8.2, Gl. (4)"},{"ws_code":"M179-08","code":"REQ-18","title_de":"Filtration: v_F = 0.05-2.5 m/h (Oberflaechenfiltration)","condition":"if filtration_surface then 0.05 <= v_F <= 2.5","description":"Surface filtration is preferred and designed for v_F = 0,05 m/h to 2,5 m/h.","clause_reference":"§7.3.2"},{"ws_code":"M179-08","code":"REQ-19","title_de":"Filtration: Filtermaechtigkeit >= 0,2 m","condition":"if filtration then filter_thickness >= 0.2","description":"Filter thickness shall be at least 0,2 m; thinner filters are not recommended.","clause_reference":"§7.3.2"},{"ws_code":"M179-08","code":"REQ-20","title_de":"Filtration: AFS63-Belastung <= 7 kg/(m²·a) fuer >= 12 Monate","condition":"if filtration then AFS63 surface loading <= 7 kg/(m²·a)","description":"Filter area AFS63 loading shall not exceed 7 kg/(m²·a) for minimum 12 months Standzeit.","clause_reference":"§7.3.2, §8.2"},{"ws_code":"M179-08","code":"REQ-21","title_de":"Filtration: A_F nach Gl. (5) (1% von A_b,a)","condition":"abs(A_F - A_b_a*0.01) < tol  OR  reduced per pre-treatment","description":"Filter area = 1% of A_b,a per Gleichung (5). With effective pre-treatment, ratio may be reduced.","clause_reference":"§8.2, Gl. (5)"},{"ws_code":"M179-08","code":"REQ-22","title_de":"Abflussaufteilung Fall 4: Mindestabfluss 5 l/s","condition":"if Fall 4 then Q_krit >= 5","description":"If Abflussaufteilung is realized by technical installations upstream of treatment (Fall 4), minimum 5 l/s must be maintained per DWA-A 166.","clause_reference":"§7.2, DWA-A 166"},{"ws_code":"M179-08","code":"REQ-23","title_de":"Vollstrombehandlung bei Zufluessen <= 5 l/s","condition":"if Q_krit <= 5 l/s then Vollstrombehandlung","description":"At inflows ≤ 5 l/s no Abflussaufteilung is possible — full-stream treatment required.","clause_reference":"§7.2"},{"ws_code":"M179-03","code":"REQ-24","title_de":"Spitzenabflussbeiwert Ψ_s = 1","condition":"Psi_s == 1","description":"Peak runoff coefficient Ψ_s is set to 1 for this Merkblatt.","clause_reference":"§8.2"},{"ws_code":"M179-14","code":"REQ-25","title_de":"Standortspez. Summe <= 1: Standardbedingungen","condition":"site_factor_sum <= 1","description":"Site-factor sum ≤ 1 corresponds to standard conditions (≥ 1-year Standzeit).","clause_reference":"§8.3, Tab.6"},{"ws_code":"M179-14","code":"REQ-26","title_de":"Standortspez. Summe >= 3: Betriebssicherheit gefaehrdet","condition":"site_factor_sum < 3","description":"Site-factor sum ≥ 3 indicates very high AFS63 accumulation → operational safety at risk → larger sludge volume or design adjustment needed.","clause_reference":"§8.3, Tab.6"},{"ws_code":"M179-16","code":"REQ-27","title_de":"Wartung durch fachkundige Personen","condition":"Qualified personnel + maintenance contract documented","description":"Control, cleaning and maintenance must be carried out by qualified personnel; maintenance contracts recommended for complex / private facilities.","clause_reference":"§9"},{"ws_code":"M179-16","code":"REQ-28","title_de":"Monitoring >= 1 Jahr empfohlen","condition":"monitoring_planned in {true, false} with rationale","description":"When investigating effectiveness, monitoring for at least 1 year is recommended (Wasserstand/Durchfluss, Saisonalitaet, AFS63-Depot).","clause_reference":"§9"},{"ws_code":"M179-16","code":"REQ-29","title_de":"Betriebsanweisung in Planungsphase erstellen","condition":"Betriebsanweisung prepared","description":"Operating instructions per DWA-A 199 Teil 1/2 must be created in the planning phase.","clause_reference":"§8.4.4, DWA-A 199"},{"ws_code":"M179-16","code":"REQ-30","title_de":"Inbetriebnahme: Funktionspruefung vorab","condition":"Funktionspruefung done && Betriebsanweisung ready before Inbetriebnahme","description":"A Funktionspruefung must be performed before Inbetriebnahme; Betriebsanweisung must exist by Inbetriebnahme.","clause_reference":"§8.4.6"},{"ws_code":"M179-16","code":"REQ-31","title_de":"Entsorgung nach DWA-M 369","condition":"Waste disposal pathway documented per DWA-M 369","description":"Waste from maintenance/cleaning must be disposed of properly (water and waste law requirements); reference DWA-M 369.","clause_reference":"§9, DWA-M 369"},{"ws_code":"M179-16","code":"REQ-32","title_de":"Dynamische Kostenvergleichsrechnung","condition":"Dynamic cost-comparison performed per KVR-Leitlinien","description":"For monetary evaluation of dezentrale Anlagen a dynamische Kostenvergleichsrechnung (KVR) must be applied.","clause_reference":"§8.4.2, KVR-Leitlinien"},{"ws_code":"M179-16","code":"REQ-33","title_de":"Klimakennung KA1 / KS1","condition":"Climate classification noted in project record","description":"DWA-M 179-1 has KA1 (indirect adaptation) and KS1 (indirect protection) climate classification per §10.2 / Tab. 7, 8.","clause_reference":"§10.2, Tab.7, Tab.8"}]}$p3c_json$::jsonb;
  v_std uuid;
BEGIN
  -- 1. standard (UPSERT by code)
  INSERT INTO standards (code, title_de, title_en, version)
  SELECT v_data->'standard'->>'code', v_data->'standard'->>'title_de',
         v_data->'standard'->>'title_en', v_data->'standard'->>'version'
  ON CONFLICT (code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, version = excluded.version;
  SELECT id INTO v_std FROM standards WHERE code = v_data->'standard'->>'code';

  -- 2. worksheet templates (UPSERT by standard_id+code)
  INSERT INTO worksheet_templates (standard_id, code, title_de, title_en, phase, archetype, order_index, description)
  SELECT v_std, w->>'code', w->>'title_de', w->>'title_en',
         (w->>'phase')::int, w->>'archetype', (w->>'order_index')::int, w->>'description'
  FROM jsonb_array_elements(v_data->'worksheets') AS w
  ON CONFLICT (standard_id, code) DO UPDATE
    SET title_de = excluded.title_de, title_en = excluded.title_en, phase = excluded.phase,
        archetype = excluded.archetype, order_index = excluded.order_index, description = excluded.description;

  -- 3. sections: null fields.section_id, wipe + reinsert (no unique constraint on code), resolve parents
  UPDATE fields SET section_id = NULL
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);
  DELETE FROM worksheet_sections
   WHERE worksheet_template_id IN (SELECT id FROM worksheet_templates WHERE standard_id = v_std);

  INSERT INTO worksheet_sections (worksheet_template_id, code, title_de, order_index)
  SELECT wt.id, s->>'code', s->>'title_de', (s->>'order_index')::int
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code';

  UPDATE worksheet_sections AS child
     SET parent_section_id = parent.id
  FROM jsonb_array_elements(v_data->'sections') AS s
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = s->>'ws_code'
  JOIN worksheet_sections parent ON parent.worksheet_template_id = wt.id AND parent.code = s->>'parent_code'
  WHERE s->>'parent_code' IS NOT NULL
    AND child.worksheet_template_id = wt.id
    AND child.code = s->>'code';

  -- 4. fields (UPSERT by worksheet_template_id+symbol; verification_status NOT touched)
  INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, label_en, data_type, unit,
                      is_required, enum_values, validation_rules, clause_reference, description, consumer_worksheets)
  SELECT wt.id,
         (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = wt.id AND ws.code = f->>'section_code' LIMIT 1),
         f->>'symbol', f->>'label_de', f->>'label_en', f->>'data_type', f->>'unit',
         (f->>'is_required')::boolean,
         CASE WHEN jsonb_typeof(f->'enum_values') = 'array' THEN f->'enum_values' ELSE NULL END,
         CASE WHEN jsonb_typeof(f->'validation_rules') = 'object' THEN f->'validation_rules' ELSE NULL END,
         f->>'clause_reference', f->>'description',
         CASE WHEN jsonb_typeof(f->'consumer_worksheets') = 'array'
              THEN ARRAY(SELECT jsonb_array_elements_text(f->'consumer_worksheets')) ELSE NULL END
  FROM jsonb_array_elements(v_data->'fields') AS f
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = f->>'ws_code'
  ON CONFLICT (worksheet_template_id, symbol) DO UPDATE
    SET section_id = excluded.section_id, label_de = excluded.label_de, label_en = excluded.label_en,
        data_type = excluded.data_type, unit = excluded.unit, is_required = excluded.is_required,
        enum_values = excluded.enum_values, validation_rules = excluded.validation_rules,
        clause_reference = excluded.clause_reference, description = excluded.description,
        consumer_worksheets = excluded.consumer_worksheets;

  -- 5. equations (UPSERT by worksheet_template_id+equation_number; verification_status preserved)
  INSERT INTO equations (worksheet_template_id, equation_number, formula, input_symbols, output_symbol, clause_reference, description)
  SELECT wt.id, e->>'equation_number', e->>'formula',
         CASE WHEN jsonb_typeof(e->'input_symbols') = 'array' THEN ARRAY(SELECT jsonb_array_elements_text(e->'input_symbols')) ELSE NULL END,
         e->>'output_symbol', e->>'clause_reference', e->>'description'
  FROM jsonb_array_elements(v_data->'equations') AS e
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = e->>'ws_code'
  ON CONFLICT (worksheet_template_id, equation_number) DO UPDATE
    SET formula = excluded.formula, input_symbols = excluded.input_symbols, output_symbol = excluded.output_symbol,
        clause_reference = excluded.clause_reference, description = excluded.description;

  -- 6. compliance requirements (UPSERT by worksheet_template_id+code)
  INSERT INTO compliance_requirements (worksheet_template_id, code, title_de, condition, description, clause_reference, severity)
  SELECT wt.id, c->>'code', c->>'title_de', c->>'condition', c->>'description', c->>'clause_reference', 'block'
  FROM jsonb_array_elements(v_data->'compliance') AS c
  JOIN worksheet_templates wt ON wt.standard_id = v_std AND wt.code = c->>'ws_code'
  ON CONFLICT (worksheet_template_id, code) DO UPDATE
    SET title_de = excluded.title_de, condition = excluded.condition, description = excluded.description,
        clause_reference = excluded.clause_reference, severity = excluded.severity;
END
$p3c_do$;
